from .wft_downloader import WFTDownloader
import logging
from functools import wraps
import os


def hub_kw(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        try:
            result = web_fun(self, *args, **kwargs)
            return result
        except Exception as ex:
            self._check_proxies()
            raise ex

    return wrapper


class wft(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._wft_obj = WFTDownloader()

    @hub_kw
    def download_hub_build_from_wft(self, build_version, destination_path='/tmp/'):
        """ Download hub build from WFT

        :param build_version: HUB build version eg: ASIHUB18.12.R01
        :param destination_path: PATH where build will be downloaded. Default /tmp/ directory
        :return: HUB build file name
        """

        hub_url = self._wft_obj.get_hub_url(hub_version=build_version)
        build_filename = self._wft_obj.get_filename_from_url(hub_url)
        if build_filename in os.listdir(destination_path):
            logging.info("Build {} already downloaded in {}".format(build_version, destination_path))
            return build_filename
        self._wft_obj.download_to_file(url=hub_url, destination_path=destination_path,
                                       user='ca_ivk_crt', password='caivkcrt')
        return build_filename

    @hub_kw
    def get_hub_build_filename(self, build_version):
        """ Get hub build file name based on URL to hub build

        :param build_version: HUB build version eg: ASIHUB18.12.R01
        :return: build_filename
        """

        hub_url = self._wft_obj.get_hub_url(hub_version=build_version)
        build_filename = self._wft_obj.get_filename_from_url(hub_url)

        return build_filename

    @hub_kw
    def get_hub_version_for_enb_version(self, enb_build_version, component_name="ASIHUB"):
        """Get compatible hub version for eNB version

        :param enb_build_version: ENB build version eg: FL18A_ENB_0000_000660_000000
        :param component_name: component name from wft, should equal to ASIHUB/ASIHUB2.0
        :return: hub_version
        """

        hub_version = self._wft_obj.get_hub_version(build_version=enb_build_version, component_name=component_name)

        return hub_version

    def download_enb_build_from_wft(self, build_version, destination_path='/tmp/'):
        """ Download enb build from WFT

        :param build_version: ENB build version eg: FL18A_ENB_0000_000660_000000
        :param destination_path: PATH where build will be downloaded. Default /tmp/ directory
        :return: enb_url: URL to ENB build
        """

        enb_url = self._wft_obj.get_enb_url(build_version=build_version)
        self._wft_obj.download_to_file(url=enb_url, destination_path=destination_path)

        return enb_url

    def set_proxies(self, proxies):
        """ Set proxies for wft_downloader object

        :param proxies: dict, eg. {'https': 'http://proxy-lab.krk-lab.nsn-rdnet.net:8080'}
        :return: None
        """
        self._wft_obj.proxies = proxies

    def _check_proxies(self):
        """ Check is proxies in wft_downloader object are set

        :return: None
        """
        if not self._wft_obj.proxies:
            logging.warn("If keyword do not work properly, consider to set proxies")

    def unset_proxies(self):
        """ Unset proxies for wft_downloader object

        :return: None
        """
        self._wft_obj.proxies = None
